mapper.select:
SELECT seb.id AS id, se.`year` AS `year`, se.semester AS semester, se.exam_type AS examType, se.exam_date AS examDate, seb.exam_id AS examId, se.`name` AS examName, seb.grade_clazz_id AS clazzId, sc.`name` AS clazzName, sc.grade_id AS gradeId, sg.`name` AS gradeName FROM sys_exam_body seb LEFT JOIN sys_exam se ON seb.exam_id = se.id LEFT JOIN sys_clazz sc ON seb.grade_clazz_id = sc.id LEFT JOIN sys_grade sg ON sc.grade_id = sg.id
seb.g_or_c = 'C'
AND ( se.name LIKE '%' || #{queryParams.keywords} || '%' OR se.code LIKE '%' || #{queryParams.keywords} || '%' )
AND se.`year` = #{queryParams.year}
AND se.semester = #{queryParams.semester}
AND se.exam_type = #{queryParams.examType}
AND seb.grade_clazz_id = #{queryParams.clazzId}
AND sc.grade_id = #{queryParams.gradeId}
order by se.exam_date desc
